/**
 * Generates a link that launches the specified app on current environment, with an optional internal route specified by pageToken
 *
 * *Note:* There is no guarantee that the specified app will be launched since different sets of apps could be installed on different platform instances.
 * Relying on explicitly hardcoded app could lead to broken UX.
 *
 * *Note:* a page token is not a URL of the page or a route in the app.
 * It is a dedicated part of the app manifest and considered as an external public API of the app that should be explicitly defined by the app developer.
 * If you're using`@dynatrace/dtp-cli`, it could be configured in `dtp.config.ts`.
 * @param {string} appId ID of the app that will be launched.
 * @param {string} [pageToken] Id of the static path segment defining an internal route in app.  *Warning:* not the same thing as URL or route.
 * @returns {string} URL to the specified app on current environment.
 */
export declare function getAppLink(appId: string, pageToken?: string | undefined): string;
